Item: O texto, que se classifica como dissertativo, expõe a articulação entre o tráfico internacional de drogas e o sistema financeiro mundial.$q$, context_review_required=false, content_status='active', current_syllabus_topic_id=(select t.id from public.syllabus_topics t join public.syllabus_editions e on e.id=t.edition_id where e.contest_name=$q$Polícia Federal$q$ and e.contest_year=2025 and e.role_name=$q$Agente de Polícia Federal$q$ and t.discipline=$q$Língua Portuguesa$q$ and t.topic_order=1 and t.block_name not ilike '%Hist%' limit 1) where exam_year=2014 and career_name=$q$Agente de Polícia Federal$q$ and item_number=17 and content_status='under_review';
