update public.official_exam_questions set review_note=$q$P → (Q∨R) e R → S; logo P → (Q∨S), que implica P → (Q∨S∨T). Fórmula conferida na imagem do caderno; gabarito C confere.$q$, question_text=$q$Texto-base:
As seguintes premissas referem-se a uma argumentação hipotética:
